7	/** Merges the `defaults` object of type `T` into the `formData` of type `T`
8	 *
9	 * When merging defaults and form data, we want to merge in this specific way:
10	 * - objects are deeply merged
11	 * - arrays are merged in such a way that:
12	 *   - when the array is set in form data, only array entries set in form data
13	 *     are deeply merged; additional entries from the defaults are ignored unless `mergeExtraArrayDefaults` is true, in
14	 *     which case the extras are appended onto the end of the form data
15	 *   - when the array is not set in form data, the default is copied over
16	 * - scalars are overwritten/set by form data unless undefined and there is a default AND `defaultSupercedesUndefined`
17	 *   is true
18	 *
19	 * @param [defaults] - The defaults to merge
20	 * @param [formData] - The form data into which the defaults will be merged
21	 * @param [mergeExtraArrayDefaults=false] - If true, any additional default array entries are appended onto the formData
22	 * @param [defaultSupercedesUndefined=false] - If true, an explicit undefined value will be overwritten by the default value
23	 * @param [overrideFormDataWithDefaults=false] - If true, the default value will overwrite the form data value. If the value
24	 *        doesn't exist in the default, we take it from formData and in the case where the value is set to undefined in formData.
25	 *       This is useful when we have already merged formData with defaults and want to add an additional field from formData
26	 *       that does not exist in defaults.
27	 * @returns - The resulting merged form data with defaults
28	 */
29	export default function mergeDefaultsWithFormData<T = any>(
30	  defaults?: T,
31	  formData?: T,
32	  mergeExtraArrayDefaults = false,
33	  defaultSupercedesUndefined = false,
34	  overrideFormDataWithDefaults = false,
35	): T | undefined {
36	  if (Array.isArray(formData)) {
37	    const defaultsArray = Array.isArray(defaults) ? defaults : [];
38	
39	    // If overrideFormDataWithDefaults is true, we want to override the formData with the defaults
40	    const overrideArray = overrideFormDataWithDefaults ? defaultsArray : formData;
41	    const overrideOppositeArray = overrideFormDataWithDefaults ? formData : defaultsArray;
42	
43	    const mapped = overrideArray.map((value, idx) => {
44	      // We want to explicitly make sure that the value is NOT undefined since null, 0 and empty space are valid values
45	      if (overrideOppositeArray[idx] !== undefined) {
46	        return mergeDefaultsWithFormData<any>(
47	          defaultsArray[idx],
48	          formData[idx],
49	          mergeExtraArrayDefaults,
50	          defaultSupercedesUndefined,
51	          overrideFormDataWithDefaults,
52	        );
53	      }
54	      return value;
55	    });
56	
57	    // Merge any extra defaults when mergeExtraArrayDefaults is true
58	    // Or when overrideFormDataWithDefaults is true and the default array is shorter than the formData array
59	    if ((mergeExtraArrayDefaults || overrideFormDataWithDefaults) && mapped.length < overrideOppositeArray.length) {
60	      mapped.push(...overrideOppositeArray.slice(mapped.length));
61	    }
62	    return mapped as unknown as T;
63	  }
64	  if (isObject(formData)) {
65	    const acc: { [key in keyof T]: any } = Object.assign({}, defaults); // Prevent mutation of source object.
66	    return Object.keys(formData as GenericObjectType).reduce((acc, key) => {
67	      const keyValue = get(formData, key);
68	      const keyExistsInDefaults = isObject(defaults) && key in (defaults as GenericObjectType);
69	      const keyExistsInFormData = key in (formData as GenericObjectType);
70	      const keyDefault = get(defaults, key) ?? {};
71	      const defaultValueIsNestedObject = keyExistsInDefaults && Object.entries(keyDefault).some(([, v]) => isObject(v));
72	
73	      const keyDefaultIsObject = keyExistsInDefaults && isObject(get(defaults, key));
74	      const keyHasFormDataObject = keyExistsInFormData && isObject(keyValue);
75	
76	      if (keyDefaultIsObject && keyHasFormDataObject && !defaultValueIsNestedObject) {
77	        acc[key as keyof T] = {
78	          ...get(defaults, key),
79	          ...keyValue,
80	        };
81	        return acc;
82	      }
83	
84	      acc[key as keyof T] = mergeDefaultsWithFormData<T>(
85	        get(defaults, key),
86	        keyValue,
87	        mergeExtraArrayDefaults,
88	        defaultSupercedesUndefined,
89	        // overrideFormDataWithDefaults can be true only when the key value exists in defaults
90	        // Or if the key value doesn't exist in formData
91	        overrideFormDataWithDefaults && (keyExistsInDefaults || !keyExistsInFormData),
92	      );
93	      return acc;
94	    }, acc);
95	  }
96	
97	  /**
98	   * If the defaultSupercedesUndefined flag is true
99	   *    And formData is set to undefined or null and defaults are defined
100	   *    Or if formData is a number and is NaN return defaults
101	   * Or if overrideFormDataWithDefaults flag is true and formData is set to not undefined/null return defaults
102	   */
103	  if (
104	    (defaultSupercedesUndefined &&
105	      ((!(defaults === undefined) && isNil(formData)) || (typeof formData === 'number' && isNaN(formData)))) ||
106	    (overrideFormDataWithDefaults && !isNil(formData))
107	  ) {
108	    return defaults;
109	  }
110	
111	  return formData;
112	}
