import isObject from './isObject';

/** Determines whether the given `value` should be considered "empty" for the purposes of pruning optional properties.
 * A value is empty when it is `undefined`, `null`, an empty string, or an empty array. Note that boolean `false` and
 * the number `0` are explicitly NOT considered empty.
 *
 * @param value - The value to check for emptiness
 * @returns - True if the `value` is considered empty, otherwise false
 */
function isEmptyValue(value: any): boolean {
  if (value === undefined || value === null || value === '') {
    return true;
  }
  if (Array.isArray(value) && value.length === 0) {
    return true;
  }
  return false;
}

/** Recursively traverses the `formData` against the given `schema` and removes any optional properties (object, scalar
 * or array) whose values are considered "empty" (`undefined`, `null`, an empty string, an empty array, or a nested
 * object that is itself fully empty after processing). Required properties (those listed in the schema's `required`
 * array) are NOT removed; if a required property's value is processed to empty, its key is retained but its value is
 * set to `undefined`. Properties present in `formData` but not defined in the `schema` are preserved as-is. When all of
 * an object's properties are pruned, `undefined` is returned instead of an empty object. Arrays are processed
 * item-by-item using the appropriate per-item schema (tuple items by index, `additionalItems` for out-of-bounds
 * indices, or as-is when no schema applies).
 *
 * @param validator - An implementation of the `ValidatorType` interface that will be forwarded to all the APIs
 * @param schema - The schema against which the `formData` is being processed
 * @param rootSchema - The root schema, used to primarily to look up `$ref`s
 * @param formData - The form data to process
 * @returns - The processed form data, or `undefined` when the data is fully empty
 */
export default function removeOptionalEmptyObjects<
  T = any,
  S extends StrictRJSFSchema = RJSFSchema,
  F extends FormContextType = any,
>(validator: ValidatorType<T, S, F>, schema: S, rootSchema: S, formData: any): any {
  if (formData === undefined) {
    return undefined;
  }

  // Non-object, non-array values are returned unchanged.
  if (!isObject(formData) && !Array.isArray(formData)) {
    return formData;
  }

  // Without a schema we cannot know what is optional, so return the data unchanged.
  if (!schema || typeof schema !== 'object') {
    return formData;
  }

  if (Array.isArray(formData)) {
    const { items, additionalItems } = schema as RJSFSchema;
    // With no `items` definition there is nothing to process against, so return the array unchanged.
    if (items === undefined) {
      return formData;
    }

    let changed = false;
    const result = formData.map((element, index) => {
      let itemSchema: any;
      if (Array.isArray(items)) {
        // Tuple schema: use the schema at the matching index, or `additionalItems` for out-of-bounds indices.
        itemSchema = index < items.length ? items[index] : additionalItems;
      } else {
        itemSchema = items;
      }

      // When no schema applies (out-of-bounds with no `additionalItems`, or a boolean schema), leave the element as-is.
      if (!itemSchema || typeof itemSchema !== 'object') {
        return element;
      }

      const processed = removeOptionalEmptyObjects<T, S, F>(validator, itemSchema as S, rootSchema, element);
      if (processed !== element) {
        changed = true;
      }
      return processed;
    });

    return changed ? result : formData;
  }

  // An object schema with no `properties` cannot be pruned, so return the data unchanged.
  const { properties } = schema as RJSFSchema;
  if (!properties || !isObject(properties)) {
    return formData;
  }

  const required = Array.isArray(schema.required) ? schema.required : [];
  const result: { [key: string]: any } = { ...(formData as object) };

  Object.keys(properties).forEach((key) => {
    if (!(key in (formData as object))) {
      return;
    }

    const propertySchema = (properties as { [key: string]: any })[key];
    const value = result[key];
    const processed =
      propertySchema && typeof propertySchema === 'object'
        ? removeOptionalEmptyObjects<T, S, F>(validator, propertySchema as S, rootSchema, value)
        : value;

    if (isEmptyValue(processed)) {
      if (required.includes(key)) {
        // Required properties are retained but cleared to `undefined`.
        result[key] = undefined;
      } else {
        delete result[key];
      }
    } else {
      result[key] = processed;
    }
  });

  // When every property has been pruned (deleted or set to `undefined`), collapse the object to `undefined`.
  const hasMeaningfulData = Object.keys(result).some((key) => result[key] !== undefined);
  if (!hasMeaningfulData) {
    return undefined;
  }

  return result;
}
